#!/bin/bash\n\n# Simple build script for NoC Simulator\n# This script attempts to build the project with basic settings\n\necho \"=== NoC Simulator Build Script ===\"\n\n# Create build directory\necho \"Creating build directory...\"\nmkdir -p build\ncd build\n\n# Check for SystemC\necho \"Checking for SystemC...\"\nSYSTEMC_PATH=\"/usr/local/systemc-2.3.3\"\nif [ ! -d \"$SYSTEMC_PATH\" ]; then\n    echo \"Warning: SystemC not found at $SYSTEMC_PATH\"\n    echo \"Please install SystemC or update SYSTEMC_PATH in this script\"\n    echo \"For now, we'll try to compile with system packages...\"\n    SYSTEMC_PATH=\"\"\nfi\n\n# Try to compile with g++ directly first (for testing)\necho \"Attempting direct compilation...\"\ng++ --version\n\necho \"Compiling source files...\"\n\n# Compile congestion model\necho \"Building CongestionModel...\"\ng++ -c -std=c++17 -I.. -I../congest_model ../congest_model/CongestionModel.cpp -o CongestionModel.o\n\nif [ $? -ne 0 ]; then\n    echo \"Error: Failed to compile CongestionModel.cpp\"\n    echo \"This might be due to missing SystemC headers.\"\n    echo \"Please ensure SystemC is properly installed.\"\n    exit 1\nfi\n\necho \"✓ CongestionModel compiled successfully\"\n\n# Note about full compilation\necho \"\"\necho \"=== Build Status ===\"\necho \"✓ CongestionModel.cpp compiles successfully\"\necho \"⚠ Full NoC simulator requires SystemC to be properly installed\"\necho \"⚠ Router and NoC_sim classes are template-based and header-only for now\"\necho \"\"\necho \"To complete the build:\"\necho \"1. Install SystemC (https://github.com/accellera-official/systemc)\"\necho \"2. Run: cmake .. && make\"\necho \"3. Or use the provided CMakeLists.txt with proper SystemC setup\"\n\necho \"\"\necho \"Build script completed. Check above for any errors.\"\n